use rusqlite::{Connection,params};
use serde_json::{Value,json};
use std::{path::Path,sync::Mutex};
pub struct Database(pub Mutex<Connection>);
impl Database {
 pub fn open(path:&Path)->Result<Self,String>{let c=Connection::open(path).map_err(|e|e.to_string())?;let version:i64=c.query_row("PRAGMA user_version",[],|r|r.get(0)).map_err(|e|e.to_string())?;if version>3{return Err("A base de dados pertence a uma versão mais recente. Atualize a aplicação.".into())}if version==0{c.execute_batch(include_str!("../migrations/001_initial.sql")).map_err(|e|e.to_string())?;}if version<2{c.execute_batch(include_str!("../migrations/002_sessions.sql")).map_err(|e|e.to_string())?;}if version<3{c.execute_batch(include_str!("../migrations/003_game_sessions.sql")).map_err(|e|e.to_string())?;}Ok(Self(Mutex::new(c)))}
 pub fn log(&self,op:&str,detail:&str)->Result<(),String>{self.0.lock().map_err(|e|e.to_string())?.execute("INSERT INTO logs(operation,detail) VALUES(?1,?2)",params![op,detail]).map_err(|e|e.to_string())?;Ok(())}
 pub fn list(&self,table:&str)->Result<Value,String>{let sql=match table{"changes"=>"SELECT * FROM changes ORDER BY id DESC","logs"=>"SELECT * FROM logs ORDER BY id DESC LIMIT 500","benchmarks"=>"SELECT * FROM benchmarks ORDER BY id DESC LIMIT 100","benchmark_runs"=>"SELECT id,created_at,label,conditions,duration_seconds,sample_count,summary FROM benchmark_runs ORDER BY id DESC LIMIT 100","fps_sessions"=>"SELECT id,created_at,label,conditions,stream,source,stats FROM fps_sessions ORDER BY id DESC LIMIT 100","game_sessions"=>"SELECT * FROM game_sessions ORDER BY id DESC LIMIT 100","profiles"=>"SELECT * FROM profiles ORDER BY id DESC","snapshots"=>"SELECT * FROM snapshots ORDER BY id DESC LIMIT 20",_=>return Err("Tabela não permitida".into())};let c=self.0.lock().map_err(|e|e.to_string())?;let mut s=c.prepare(sql).map_err(|e|e.to_string())?;let cols:Vec<String>=s.column_names().iter().map(|x|x.to_string()).collect();let rows=s.query_map([],|row|{let mut obj=serde_json::Map::new();for(i,n)in cols.iter().enumerate(){let v=match row.get_ref(i)?{rusqlite::types::ValueRef::Integer(n)=>json!(n),rusqlite::types::ValueRef::Real(n)=>json!(n),rusqlite::types::ValueRef::Text(t)=>json!(String::from_utf8_lossy(t)),_=>Value::Null};obj.insert(n.clone(),v);}Ok(Value::Object(obj))}).map_err(|e|e.to_string())?;Ok(Value::Array(rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?))}
}
#[cfg(test)] mod tests {use super::*;#[test]fn migration_and_allowlist(){let d=Database::open(Path::new(":memory:")).unwrap();d.log("test","ok").unwrap();assert_eq!(d.list("logs").unwrap().as_array().unwrap().len(),1);assert!(d.list("logs; DROP TABLE changes").is_err());}}
